(()=>{
const sidebar=document.querySelector('.sidebar');const cards=[...sidebar.children];
const tabs=document.createElement('nav');tabs.className='workspace-tabs';tabs.setAttribute('aria-label','Workspace');tabs.innerHTML=['Data','Design','Results','Field'].map((n,i)=>`<button type="button" data-panel="${n}" aria-pressed="${i===0}"><span>0${i+1}</span>${n}</button>`).join('');sidebar.before(tabs);
const intro=document.createElement('div');intro.className='workspace-intro';intro.innerHTML='<div><span class="eyebrow">PROJECT WORKSPACE</span><h2>Explore your reserve.</h2></div><span class="local-badge">● LOCAL FIRST</span>';sidebar.prepend(intro);
const groups={Data:[],Design:[],Results:[],Field:[]};cards.forEach(c=>{const t=c.querySelector('h2')?.textContent||'';const key=/POLYGON &|CATATAN/.test(t)?'Design':/RINGKASAN/.test(t)?'Results':/COLLAR|TOOLS/.test(t)?'Field':'Data';groups[key].push(c);});
const help=document.createElement('section');help.className='card welcome-card';help.innerHTML='<span class="eyebrow">A VERIFIED STARTING POINT</span><h2>Your original project. A clearer workflow.</h2><p>Snapshot 25 Oct 2026 · original block model and georeferenced orthophoto preview.</p><ol><li>Review or import your CSV.</li><li>Draw a boundary in Design.</li><li>Compare stage and total in Results.</li></ol><p>Fixed grid: <b>12.5 × 12.5 × 1 m</b><br>CRS: <b>WGS84 / UTM 51S</b></p><button id="goDesign" class="primary">Start a design →</button>';sidebar.append(help);groups.Data.push(help);
const dataHelp=document.createElement('section');dataHelp.className='card';dataHelp.innerHTML='<h2>Validation before calculation</h2><p class="subtext">X, Y, Z, Ni, Fe and density are required. Missing grades, non-positive density and duplicate XYZ records are rejected. The previous dataset stays available when validation fails.</p><a href="./data/template.csv" download>Download CSV template ↗</a><p class="subtext">Imports are stored in this browser. Export important work; clearing site data removes local copies. Drive sync is not connected in this version.</p>';sidebar.append(dataHelp);groups.Data.push(dataHelp);
function show(name){for(const [key,items]of Object.entries(groups))for(const c of items)c.hidden=key!==name;for(const b of tabs.children)b.setAttribute('aria-pressed',String(b.dataset.panel===name));intro.querySelector('h2').textContent={Data:'Explore your reserve.',Design:'Define the next stage.',Results:'Understand the numbers.',Field:'Connect model to field.'}[name];sidebar.scrollTop=0;window.dispatchEvent(new Event('resize'));}
tabs.onclick=e=>{const b=e.target.closest('button');if(b)show(b.dataset.panel);};document.getElementById('goDesign').onclick=()=>show('Design');show('Data');
const quick=document.createElement('div');quick.className='quick-actions';quick.innerHTML='<span>PLAN YOUR NEXT CUT</span><button id="quickDraw" class="primary">＋ Draw polygon</button><button id="quickExtent">Full model</button><button id="quickResults">Results ↗</button>';document.querySelector('.map-head').after(quick);
document.getElementById('quickDraw').onclick=()=>{show('Design');document.getElementById('drawBtn').click();};document.getElementById('quickExtent').onclick=()=>{document.getElementById('boxBtn').click();show('Results');};document.getElementById('quickResults').onclick=()=>show('Results');
// Project JSON is portable between devices; inputs never contain credentials.
const portable=document.createElement('section');portable.className='card';portable.innerHTML='<h2>Save your design</h2><p class="subtext">Export polygon, depth and display settings. Load the matching CSV before restoring a design.</p><div class="button-row"><button id="saveDesign">Export design JSON</button><button id="restoreDesign">Import design JSON</button></div><input id="designFile" type="file" accept=".json" hidden>';sidebar.append(portable);groups.Design.push(portable);portable.hidden=true;
document.getElementById('saveDesign').onclick=()=>{const raw=localStorage.getItem('minereserve-workbench-design-v2');if(!raw){alert('Draw a polygon first.');return;}const blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mine-reserve-design.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.getElementById('restoreDesign').onclick=()=>document.getElementById('designFile').click();document.getElementById('designFile').onchange=async e=>{try{const s=JSON.parse(await e.target.files[0].text());if(!Array.isArray(s.floorPoly)||s.floorPoly.length<3||s.floorPoly.length>10000||!s.floorPoly.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)))throw Error('Invalid polygon');localStorage.setItem('minereserve-workbench-design-v2',JSON.stringify(s));location.reload();}catch(err){alert('Cannot import design: '+err.message);}};
})();
